#define TF_APN_PAGES_H
typedef struct{char id[65],name[129],apn[129],username[257],password[257];int auth,pdp;} tf_apn_profile;
static tf_apn_profile apn_profiles[16];static int apn_count=0,apn_mode=-1,apn_selected=-1,apn_clear_password=0,apn_valid=0;
static char apn_edit_id[65]="";
static char apn_prior_ids[16][65];static int apn_prior_count=0;
static char apn_enabled[65]="",apn_message[192]="尚未读取";
static int apn_parse(const char*response){tf_json d;apn_valid=0;apn_count=0;apn_mode=-1;*apn_enabled=0;if(!tf_control_success(response,"{\"action\":\"apn.list\"}")||!tf_parse(&d,response))return 0;int r=tf_key(&d,0,"result"),m=tf_key(&d,r,"mode"),enabled=tf_key(&d,r,"enabled"),manual=tf_key(&d,tf_key(&d,r,"manual"),"apnListArray"),automatic=tf_key(&d,tf_key(&d,r,"automatic"),"apnListArray");long long mode;int ok=tf_int(&d,tf_key(&d,m,"apn_mode"),&mode)&&(mode==0||mode==1)&&tf_gets(&d,enabled,"profileId",apn_enabled,sizeof apn_enabled)&&manual>=0&&d.t[manual].type=='['&&automatic>=0&&d.t[automatic].type=='[';if(ok){apn_mode=(int)mode;for(int i=manual+1;i<d.t[manual].next;i=d.t[i].next){if(apn_count>=16){ok=0;break;}tf_apn_profile*p=&apn_profiles[apn_count];memset(p,0,sizeof *p);p->auth=p->pdp=-1;if(!tf_gets(&d,i,"profileId",p->id,sizeof p->id)||!*p->id||!tf_gets(&d,i,"profilename",p->name,sizeof p->name)||!tf_gets(&d,i,"wanapn",p->apn,sizeof p->apn)){ok=0;break;}for(char*s=p->id;*s;s++)if(!isalnum((unsigned char)*s)&&!strchr("_.-",*s))ok=0;tf_gets(&d,i,"username",p->username,sizeof p->username);tf_gets(&d,i,"password",p->password,sizeof p->password);long long v;if(tf_int(&d,tf_key(&d,i,"pppAuthMode"),&v)&&v>=0&&v<=3)p->auth=(int)v;if(tf_int(&d,tf_key(&d,i,"pdpType"),&v)&&v>=1&&v<=3)p->pdp=(int)v;apn_count++;}}tf_free(&d);apn_valid=ok;return ok;}
static int apn_target(void){return !strcmp(modem_selected,"4G1")?201:!strcmp(modem_selected,"4G2")?101:1;}
static int apn_load(void){char*body=malloc(65536);if(!body)return 0;int code=0;if(apn_target()==1)code=tf_http(9460,"POST","/control",NULL,"{\"action\":\"apn.list\",\"params\":{}}",body,65536);else{const char*methods[]={"get_apn_mode","getAutoApnList","getManuApnList","get_enabled_manu_apn_id"},*keys[]={"mode","automatic","manual","enabled"};size_t n=(size_t)snprintf(body,65536,"{\"ok\":true,\"action\":\"apn.list\",\"result\":{");char*part=malloc(16000);int success=part!=NULL;for(int i=0;i<4&&success;i++){success=vendor_apn_read(apn_target(),methods[i],part,16000);tf_json parsed;if(success){success=tf_parse(&parsed,part);if(success){success=parsed.t[0].type=='{';tf_free(&parsed);}}if(success)n+=(size_t)snprintf(body+n,65536-n,"%s\"%s\":%s",i?",":"",keys[i],part);}if(part){memset(part,0,16000);free(part);}if(success&&n+3<65536){snprintf(body+n,65536-n,"}}");code=200;}}int ok=code==200&&apn_parse(body);memset(body,0,65536);free(body);snprintf(apn_message,sizeof apn_message,"%s",ok?"当前卡 APN 已读取":"APN 四项配置读取不完整，禁止修改");if(!ok)apn_valid=0;return ok;}
static int apn_payload(char*out,size_t cap){if(!apn_valid||apn_selected< -1||apn_selected>=apn_count||(apn_selected<0&&apn_target()!=1))return 0;tf_apn_profile empty={0};tf_apn_profile*p=apn_selected<0?&empty:&apn_profiles[apn_selected];if(apn_selected>=0&&(!*apn_edit_id||strcmp(p->id,apn_edit_id)))return 0;if(!*form_values[0]||strlen(form_values[0])>64||!*form_values[1]||strlen(form_values[1])>128||strlen(form_values[2])>256||strlen(form_values[3])>256)return 0;char id[256],name[512],apn[1024],username[2048],password[2048];if(!tf_quote(id,sizeof id,p->id)||!tf_quote(name,sizeof name,form_values[0])||!tf_quote(apn,sizeof apn,form_values[1])||!tf_quote(username,sizeof username,form_values[2])||!tf_quote(password,sizeof password,form_values[3]))return 0;int n=apn_selected<0?snprintf(out,cap,"{\"action\":\"apn.add\",\"params\":{\"slot_id\":1,\"name\":%s,\"apn\":%s",name,apn):snprintf(out,cap,"{\"action\":\"apn.modify\",\"params\":{\"slot_id\":%d,\"profile_id\":%s,\"name\":%s,\"apn\":%s",apn_target(),id,name,apn);if(n<0||(size_t)n>=cap)return 0;size_t len=(size_t)n;if(strcmp(form_values[2],form_original[2]))len+=(size_t)snprintf(out+len,cap-len,",\"username\":%s",username);if(*form_values[3]||apn_clear_password)len+=(size_t)snprintf(out+len,cap-len,",\"password\":%s",password);if(strcmp(form_values[4],form_original[4]))len+=(size_t)snprintf(out+len,cap-len,",\"auth_mode\":%d",atoi(form_values[4]));if(strcmp(form_values[5],form_original[5]))len+=(size_t)snprintf(out+len,cap-len,",\"pdp_type\":%d",atoi(form_values[5]));if(len+3>=cap)return 0;snprintf(out+len,cap-len,"}}");return 1;}
static void apn_render(void){char title[64];snprintf(title,sizeof title,"APN · %s",modem_selected);advanced_shell(title);char msg[1024];esc(msg,sizeof msg,apn_message);ah("<p class='note'>%s</p><a class='button secondary' href='act:apn-refresh' style='margin:8px 0'>重新读取 APN</a>",msg);if(apn_valid){if(apn_target()==1&&apn_count<16)ah("<a class='button' href='act:apn-add' style='margin-bottom:8px'>新增主卡 APN</a>");ah("<a class='button secondary' href='act:apn-mode:%d' style='margin-bottom:8px'>当前%s · 切换%s</a>",!apn_mode,apn_mode?"手动":"自动",apn_mode?"自动":"手动");for(int i=0;i<apn_count;i++){char name[1024],apn[1024];esc(name,sizeof name,apn_profiles[i].name);esc(apn,sizeof apn,apn_profiles[i].apn);ah("<div class='card'><b style='word-break:break-all'>%s%s</b><p class='note' style='word-break:break-all'>%s</p><a class='button secondary' href='act:apn-edit:%d' style='margin-top:7px'>编辑配置</a><a class='button secondary' href='act:apn-enable:%d' style='margin-top:7px'>启用此手动配置</a></div>",!strcmp(apn_profiles[i].id,apn_enabled)?"当前 · ":"",name,apn,i,i);if(apn_target()==1)ah("<a class='button secondary' href='act:apn-delete:%d' style='margin-bottom:8px'>删除此主卡配置</a>",i);}if(!apn_count)ah("<div class='hint'>没有手动 APN 配置</div>");}ah("<p class='note'>使用设备已有 APN 配置，修改后读取同一卡片进行验证。外卡列表不会错误复用主卡数据。</p></div></body></html>");}
static int apn_action(const char*a){ if(!strcmp(a,"apn-add")){if(apn_valid&&apn_target()==1&&apn_count<16){form_reset();form_kind=3;apn_selected=-1;apn_edit_id[0]=0;strcpy(form_values[4],"0");strcpy(form_values[5],"3");strcpy(form_original[4],"-1");strcpy(form_original[5],"-1");apn_prior_count=apn_count;for(int i=0;i<apn_count;i++)snprintf(apn_prior_ids[i],65,"%s",apn_profiles[i].id);apn_clear_password=0;advanced_page=6;scroll_y=0;}return 1;}
 if(!strncmp(a,"apn-delete:",11)){char*end;long i=strtol(a+11,&end,10);if(advanced_page!=5||!apn_valid||apn_target()!=1||*end||i<0||i>=apn_count||!control_guard())return 1;char id[256];if(!tf_quote(id,sizeof id,apn_profiles[i].id))return 1;snprintf(form_payload,sizeof form_payload,"{\"action\":\"apn.delete\",\"params\":{\"slot_id\":1,\"profile_id\":%s}}",id);strcpy(pending,"@apn");snprintf(pending_label,sizeof pending_label,"删除主卡 APN 配置 %s。此项会移除保存的配置，可能影响拨号，确认后不能在屏幕自动撤销。",apn_profiles[i].name);scroll_y=0;return 1;}if(!strcmp(a,"apn-open")||!strcmp(a,"apn-refresh")){advanced_page=5;scroll_y=0;show_busy("正在读取当前卡 APN");apn_load();return 1;}if(!strncmp(a,"apn-edit:",9)){char*end;long i=strtol(a+9,&end,10);if(!*end&&apn_valid&&i>=0&&i<apn_count){form_reset();form_kind=3;apn_selected=(int)i;tf_apn_profile*p=&apn_profiles[i];snprintf(apn_edit_id,sizeof apn_edit_id,"%s",p->id);snprintf(form_values[0],513,"%s",p->name);snprintf(form_values[1],513,"%s",p->apn);snprintf(form_values[2],513,"%s",p->username);snprintf(form_values[4],513,"%d",p->auth);snprintf(form_values[5],513,"%d",p->pdp);memcpy(form_original,form_values,sizeof form_values);apn_clear_password=0;advanced_page=6;scroll_y=0;}return 1;}
 if(!strncmp(a,"apn-auth:",9)||!strncmp(a,"apn-pdp:",8)){int auth=a[4]=='a',offset=auth?9:8;if(form_kind==3&&advanced_page==6&&strlen(a+offset)==1&&a[offset]>=(auth?'0':'1')&&a[offset]<='3')snprintf(form_values[auth?4:5],513,"%c",a[offset]);return 1;}
 if(!strcmp(a,"apn-clear-password")){if(form_kind==3&&advanced_page==6){apn_clear_password=!apn_clear_password;if(apn_clear_password)memset(form_values[3],0,513);}return 1;}
 if(!strncmp(a,"apn-mode:",9)||!strncmp(a,"apn-enable:",11)){if(advanced_page!=5||!apn_valid||!control_guard())return 1;char*end;int mode=!strncmp(a,"apn-mode:",9);long value=strtol(a+(mode?9:11),&end,10);if(*end||value<0||value>=(mode?2:apn_count))return 1;if(mode)snprintf(form_payload,sizeof form_payload,"{\"action\":\"apn.set_mode\",\"params\":{\"slot_id\":%d,\"mode\":%ld}}",apn_target(),value);else{char id[512];if(!tf_quote(id,sizeof id,apn_profiles[value].id))return 1;snprintf(form_payload,sizeof form_payload,"{\"action\":\"apn.enable\",\"params\":{\"slot_id\":%d,\"profile_id\":%s}}",apn_target(),id);}strcpy(pending,"@apn");snprintf(pending_label,sizeof pending_label,"%s当前卡 APN 配置，可能引起重新拨号。确认后提交一次并回读状态。",mode?(value?"切换手动":"切换自动"):"启用所选");scroll_y=0;return 1;}return 0;}
static int apn_verify_payload(const char*payload){tf_json d;if(!apn_valid||!tf_parse(&d,payload))return 0;int p=tf_key(&d,0,"params"),ok=0;char action[64],id[65];tf_gets(&d,0,"action",action,sizeof action);if(!strcmp(action,"apn.set_mode")){long long wanted;ok=tf_int(&d,tf_key(&d,p,"mode"),&wanted)&&wanted==apn_mode;}else if(!strcmp(action,"apn.add")){char name[129],apn[129];if(tf_gets(&d,p,"name",name,sizeof name)&&tf_gets(&d,p,"apn",apn,sizeof apn))for(int i=0;i<apn_count;i++){int old=0;for(int k=0;k<apn_prior_count;k++)if(!strcmp(apn_profiles[i].id,apn_prior_ids[k]))old=1;if(!old&&!strcmp(name,apn_profiles[i].name)&&!strcmp(apn,apn_profiles[i].apn)){ok=1;const char*keys[]={"username","password"},*actual[]={apn_profiles[i].username,apn_profiles[i].password};for(int k=0;k<2;k++)if(tf_key(&d,p,keys[k])>=0){char wanted[513];ok=ok&&tf_gets(&d,p,keys[k],wanted,sizeof wanted)&&!strcmp(wanted,actual[k]);}long long v;if(tf_key(&d,p,"auth_mode")>=0)ok=ok&&tf_int(&d,tf_key(&d,p,"auth_mode"),&v)&&v==apn_profiles[i].auth;if(tf_key(&d,p,"pdp_type")>=0)ok=ok&&tf_int(&d,tf_key(&d,p,"pdp_type"),&v)&&v==apn_profiles[i].pdp;}}}else if(tf_gets(&d,p,"profile_id",id,sizeof id)){if(!strcmp(action,"apn.delete")){ok=1;for(int i=0;i<apn_count;i++)if(!strcmp(id,apn_profiles[i].id))ok=0;}else if(!strcmp(action,"apn.enable"))ok=!strcmp(id,apn_enabled);else for(int i=0;i<apn_count;i++)if(!strcmp(id,apn_profiles[i].id)){const char*keys[]={"name","apn","username","password"},*actual[]={apn_profiles[i].name,apn_profiles[i].apn,apn_profiles[i].username,apn_profiles[i].password};ok=1;for(int k=0;k<4;k++)if(tf_key(&d,p,keys[k])>=0){char wanted[513];ok=ok&&tf_gets(&d,p,keys[k],wanted,sizeof wanted)&&!strcmp(wanted,actual[k]);}long long v;if(tf_key(&d,p,"auth_mode")>=0)ok=ok&&tf_int(&d,tf_key(&d,p,"auth_mode"),&v)&&v==apn_profiles[i].auth;if(tf_key(&d,p,"pdp_type")>=0)ok=ok&&tf_int(&d,tf_key(&d,p,"pdp_type"),&v)&&v==apn_profiles[i].pdp;break;}}tf_free(&d);return ok;}
/* The editor is bound to profile ID, never the order of a refreshed list.
 * Read again after confirmation and compare the user's baseline. No setter
 * runs when UFI edited/deleted/replaced this profile while the draft was open. */
static int apn_submit_baseline(void){
 tf_json d;if(!tf_parse(&d,form_payload))return 0;char action[64]="",id[65]="";int p=tf_key(&d,0,"params");long long slot=-1;
 int okay=tf_gets(&d,0,"action",action,sizeof action)&&tf_int(&d,tf_key(&d,p,"slot_id"),&slot)&&slot==apn_target();
 int add=!strcmp(action,"apn.add"),mode=!strcmp(action,"apn.set_mode"),modify=!strcmp(action,"apn.modify");
 if(!add&&!mode)okay=okay&&tf_gets(&d,p,"profile_id",id,sizeof id)&&*id;tf_free(&d);if(!okay)return 0;
 int prior_mode=apn_mode,prior=-1;for(int i=0;i<apn_count;i++)if(!strcmp(apn_profiles[i].id,id)){prior=i;break;}
 char name[129]="",value[129]="",user[257]="";int auth=-1,pdp=-1;
 if(!add&&!mode){if(prior<0)return 0;if(modify){if(strcmp(id,apn_edit_id))return 0;snprintf(name,sizeof name,"%s",form_original[0]);snprintf(value,sizeof value,"%s",form_original[1]);snprintf(user,sizeof user,"%s",form_original[2]);auth=atoi(form_original[4]);pdp=atoi(form_original[5]);}
 else{tf_apn_profile*q=&apn_profiles[prior];snprintf(name,sizeof name,"%s",q->name);snprintf(value,sizeof value,"%s",q->apn);snprintf(user,sizeof user,"%s",q->username);auth=q->auth;pdp=q->pdp;}}
 if(!apn_load())return 0;if(mode)return apn_mode==prior_mode;
 if(add){if(apn_target()!=1||apn_count>=16)return 0;apn_prior_count=apn_count;for(int i=0;i<apn_count;i++)snprintf(apn_prior_ids[i],65,"%s",apn_profiles[i].id);return 1;}
 int found=-1;for(int i=0;i<apn_count;i++)if(!strcmp(apn_profiles[i].id,id)){if(found>=0)return 0;found=i;}if(found<0)return 0;
 if(modify)apn_selected=found;tf_apn_profile*q=&apn_profiles[found];return !strcmp(name,q->name)&&!strcmp(value,q->apn)&&!strcmp(user,q->username)&&auth==q->auth&&pdp==q->pdp;
}
static int apn_submit(void){char response[8192];show_busy("正在核对 APN 当前配置");if(!apn_submit_baseline()||!control_guard()){memset(form_payload,0,sizeof form_payload);show_notice("APN 已在其他页面变化或读取失败；未覆盖当前配置，请返回列表重新读取");return 0;}show_busy("正在更新 APN");int accepted=tf_http_timeout(9460,"POST","/control",NULL,form_payload,response,sizeof response,10000)==200&&tf_control_success(response,form_payload);int verified=accepted&&apn_load()&&apn_verify_payload(form_payload);show_notice(verified?"APN 状态回读一致，修改已生效":accepted?"APN 请求已接受，但回读未确认；未自动重试":"APN 修改未确认；未自动重试");snprintf(verification_message,sizeof verification_message,"%s",notice);memset(response,0,sizeof response);memset(form_payload,0,sizeof form_payload);memset(form_values[3],0,513);advanced_page=5;scroll_y=0;return verified;}
